let state=loadState(),session=null,cardIndex=0,flipped=false,mockTimer=null,mockEnds=0;
function loadState(){try{const s=JSON.parse(localStorage.getItem("atest-state")||"{}");return {stats:s.stats||{},known:s.known||{},missed:s.missed||{},mocks:s.mocks||[],reviews:s.reviews||{},domains:s.domains||{},domainEvidence:s.domainEvidence||{}}}catch{return {stats:{},known:{},missed:{},mocks:[],reviews:{},domains:{},domainEvidence:{}}}}
function save(){localStorage.setItem("atest-state",JSON.stringify(state))}
function logo(sizeClass=""){return '<span class="'+sizeClass+' brand-logo"><img src="assets/a-test-logo.png" alt="A-Test official logo" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'block\'"><svg style="display:none" viewBox="0 0 100 100"><circle cx="50" cy="50" r="43" fill="none" stroke="currentColor" stroke-width="5"/><path d="M24 72h20V55c-9-4-14-12-14-22 0-16 12-27 28-27 18 0 31 13 31 31 0 9-4 18-11 24v11h-17V47" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><path d="M42 66V43M58 69V28M73 60V39" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"/><circle cx="42" cy="39" r="6" fill="currentColor"/><circle cx="58" cy="23" r="6" fill="currentColor"/><circle cx="73" cy="34" r="6" fill="currentColor"/><path d="M18 80h64" stroke="currentColor" stroke-width="6" stroke-linecap="round"/></svg></span>'}
function pct(id){const s=state.stats[id]||{c:0,t:0};return s.t?Math.round(s.c/s.t*100):0}
function nextAction(){if(Object.values(state.missed).some(n=>n>0))return {label:"Review unresolved mistakes",view:"mistakes"};if((state.stats.values||{}).t&&pct("values")<100)return {label:"Strengthen Australian Values",view:"values"};const seen=Object.keys(topicInfo).filter(id=>(state.stats[id]||{}).t);if(!seen.length)return {label:"Start your first lesson",view:"learn"};const weak=Object.keys(topicInfo).sort((a,b)=>pct(a)-pct(b))[0];if(pct(weak)<80)return {label:"Train "+topicInfo[weak].name,topic:weak};return {label:"Take a mock exam",view:"mock"}}
function coverage(){const studied=curriculumV2.map(p=>({id:p.id,total:p.domains.length,mastered:Math.round(p.domains.length*Math.min(1,pct(p.id)/100))}));const total=studied.reduce((a,x)=>a+x.total,0),done=studied.reduce((a,x)=>a+x.mastered,0);return {parts:studied,total,done,pct:Math.round(done/total*100)}}
function syllabus(){const all=curriculumV2.flatMap(p=>p.domains),seen=all.filter(d=>(state.domains[d[0]]||0)>0).length,understood=all.filter(d=>(state.domains[d[0]]||0)>=2).length,verified=all.filter(d=>(state.domains[d[0]]||0)>=3).length;app.innerHTML=pageHead("CURRICULUM","Complete testable syllabus","Every domain has a canonical teaching object. Open a domain to learn the exact concept.")+'<section class="card coverage-summary"><div class="eyebrow">DOMAIN COVERAGE</div><h2>'+verified+' verified · '+understood+' understood · '+seen+' encountered · '+all.length+' total</h2><div class="progress-bar"><i style="width:'+Math.round(verified/all.length*100)+'%"></i></div></section><div class="curriculum-grid">'+curriculumV2.map(p=>'<article class="card curriculum-part"><div class="eyebrow">PART '+p.part+'</div><h2>'+topicInfo[p.id].icon+' '+p.title+'</h2><div class="domain-list">'+p.domains.map(d=>'<button class="domain-row domain-button" data-domain="'+d[0]+'"><span class="'+((state.domains[d[0]]||0)>=3?"domain-ok":"domain-open")+'">'+((state.domains[d[0]]||0)>=3?"✓":(state.domains[d[0]]||0)===2?"◆":(state.domains[d[0]]||0)===1?"◐":"○")+'</span><span>'+d[1]+'</span></button>').join("")+'</div></article>').join("")+'</div>'}
function openDomain(id){const d=domainKnowledge[id];state.domains[id]=Math.max(1,state.domains[id]||0);save();app.innerHTML=pageHead("DOMAIN STUDY",d.title,"One canonical concept. Learn it, remember the cue, then practise its parent part.")+'<article class="card domain-study"><div class="eyebrow">'+topicInfo[d.part].icon+' '+topicInfo[d.part].name+'</div><p class="lead">'+d.teach+'</p><div class="visual">'+d.cue+'</div><div class="actions"><button class="primary" data-domain-master="'+id+'">Mark understood</button><button data-topic="'+d.part+'">Practise this part</button><button data-view="syllabus">Back to curriculum</button></div></article>'}
function glossary(){
  const cards=testableGlossary.map(function(x){return '<article class="card"><h3>'+x[0]+'</h3><p>'+x[1]+'</p></article>'}).join("");
  app.innerHTML=pageHead("TESTABLE GLOSSARY","Know the language of the test","Key terms drawn from the official testable glossary.")+'<div class="cards">'+cards+'</div><div class="actions"><button class="primary" data-view="game">Practise keywords</button><button data-view="syllabus">Back to curriculum</button></div>';
}
